#!/usr/bin/env python3
"""Validate ArchFlow Design Graph and BuildPlan before MCP execution."""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import Any


PROVENANCE = {"observed", "documented", "inferred", "user_confirmed", "generated"}


def load_json(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"cannot read valid JSON from {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError(f"root must be an object: {path}")
    return value


def digest_json(value: dict[str, Any]) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def duplicate_ids(items: list[Any]) -> set[str]:
    seen: set[str] = set()
    duplicates: set[str] = set()
    for item in items:
        if isinstance(item, dict) and isinstance(item.get("id"), str):
            item_id = item["id"]
            if item_id in seen:
                duplicates.add(item_id)
            seen.add(item_id)
    return duplicates


def validate_graph(graph: dict[str, Any], errors: list[str], warnings: list[str]) -> None:
    for key in ("schema_version", "project_id", "units", "sources", "objects"):
        if key not in graph:
            errors.append(f"design graph missing `{key}`")

    sources = graph.get("sources", [])
    objects = graph.get("objects", [])
    if not isinstance(sources, list):
        errors.append("design graph `sources` must be an array")
        sources = []
    if not isinstance(objects, list):
        errors.append("design graph `objects` must be an array")
        objects = []

    for item_id in duplicate_ids(sources):
        errors.append(f"duplicate source id: {item_id}")
    for item_id in duplicate_ids(objects):
        errors.append(f"duplicate object id: {item_id}")

    source_ids = {item.get("id") for item in sources if isinstance(item, dict)}
    object_ids = {item.get("id") for item in objects if isinstance(item, dict)}
    for obj in objects:
        if not isinstance(obj, dict):
            errors.append("every design graph object must be an object")
            continue
        parent_id = obj.get("parent_id")
        if parent_id and parent_id != "project_root" and parent_id not in object_ids:
            errors.append(f"{obj.get('id')}: unknown parent_id `{parent_id}`")
        for dimension_name, dimension in obj.get("dimensions", {}).items():
            if not isinstance(dimension, dict):
                errors.append(f"{obj.get('id')}.{dimension_name}: dimension must be an object")
                continue
            provenance = dimension.get("provenance")
            if provenance not in PROVENANCE:
                errors.append(f"{obj.get('id')}.{dimension_name}: invalid provenance `{provenance}`")
            for ref in dimension.get("evidence_refs", []):
                if ref not in source_ids:
                    errors.append(f"{obj.get('id')}.{dimension_name}: unknown evidence ref `{ref}`")
            if provenance == "inferred" and "confidence" not in dimension:
                warnings.append(f"{obj.get('id')}.{dimension_name}: inferred value lacks confidence")


def validate_plan(
    graph: dict[str, Any], plan: dict[str, Any], errors: list[str], warnings: list[str]
) -> None:
    for key in ("schema_version", "project_id", "run_id", "design_graph_digest", "steps"):
        if key not in plan:
            errors.append(f"BuildPlan missing `{key}`")
    if plan.get("project_id") != graph.get("project_id"):
        errors.append("BuildPlan project_id does not match Design Graph")

    expected_digest = digest_json(graph)
    if plan.get("design_graph_digest") != expected_digest:
        errors.append(
            "BuildPlan design_graph_digest does not match canonical Design Graph digest "
            f"({expected_digest})"
        )

    steps = plan.get("steps", [])
    if not isinstance(steps, list):
        errors.append("BuildPlan `steps` must be an array")
        return
    for step_id in duplicate_ids(steps):
        errors.append(f"duplicate step id: {step_id}")

    step_ids = {step.get("id") for step in steps if isinstance(step, dict)}
    source_ids = {item.get("id") for item in graph.get("sources", []) if isinstance(item, dict)}
    for step in steps:
        if not isinstance(step, dict):
            errors.append("every BuildPlan step must be an object")
            continue
        step_id = step.get("id", "<unknown>")
        for key in (
            "object", "action", "parameters", "depends_on", "tag",
            "component_strategy", "risk", "evidence_refs", "preconditions",
            "postconditions", "rollback_group", "qa_view",
        ):
            if key not in step:
                errors.append(f"{step_id}: missing `{key}`")
        for dependency in step.get("depends_on", []):
            if dependency not in step_ids:
                errors.append(f"{step_id}: unknown dependency `{dependency}`")
        for ref in step.get("evidence_refs", []):
            if ref not in source_ids and not str(ref).startswith("constraint:"):
                errors.append(f"{step_id}: unknown evidence ref `{ref}`")
        if not step.get("postconditions"):
            warnings.append(f"{step_id}: no measurable postconditions")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--design-graph", required=True, type=Path)
    parser.add_argument("--buildplan", required=True, type=Path)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()

    errors: list[str] = []
    warnings: list[str] = []
    try:
        graph = load_json(args.design_graph)
        plan = load_json(args.buildplan)
        validate_graph(graph, errors, warnings)
        validate_plan(graph, plan, errors, warnings)
    except ValueError as exc:
        errors.append(str(exc))

    result = {
        "status": "invalid" if errors else ("valid_with_warnings" if warnings else "valid"),
        "errors": errors,
        "warnings": warnings,
    }
    rendered = json.dumps(result, ensure_ascii=False, indent=2)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(rendered + "\n", encoding="utf-8")
    print(rendered)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
